import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../../context/ThemeContext';
import { useLanguageContext } from '../../context/LanguageContext';
import { useNews } from '../../context/NewsContext';
import './NewsSlider.css';

const NewsSlider = () => {
  const { colors, isDarkMode } = useTheme();
  const { t, language } = useLanguageContext();
  const { news } = useNews();
  
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  const activeNews = news.length > 0 ? news : [];

  // اتوپلی
  useEffect(() => {
    if (isPaused || activeNews.length <= 1) return;
    const interval = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % activeNews.length);
    }, 4000);
    return () => clearInterval(interval);
  }, [isPaused, activeNews.length]);

  const categoryIcons = {
    general: '📋', tournament: '🏆', update: '🔄', event: '🎉', team: '👥',
  };

  const categoryColors = {
    general: '#2196F3', tournament: '#FF9800', update: '#4CAF50', event: '#9C27B0', team: '#E91E63',
  };

  const categoryLabels = {
    fa: { general: 'عمومی', tournament: 'تورنمنت', update: 'بروزرسانی', event: 'رویداد', team: 'تیم' },
    en: { general: 'General', tournament: 'Tournament', update: 'Update', event: 'Event', team: 'Team' },
  };

  // اگه خبری نیست
  if (activeNews.length === 0) {
    return (
      <div className="news-slider-wrapper" style={{ direction: language === 'fa' ? 'rtl' : 'ltr' }}>
        <div className="container">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            style={{
              background: `${colors.card}ee`,
              border: `1px solid ${colors.border}`,
              borderRadius: '24px',
              padding: '60px 30px',
              textAlign: 'center',
              backdropFilter: 'blur(20px)',
            }}
          >
            <motion.div
              animate={{ scale: [1, 1.1, 1], rotate: [0, 10, -10, 0] }}
              transition={{ duration: 2, repeat: Infinity }}
              style={{ fontSize: '4rem', marginBottom: '20px' }}
            >
              🛸
            </motion.div>
            <h3 style={{ color: colors.text, fontSize: '1.5rem', marginBottom: '10px' }}>
              {language === 'fa' ? 'خبری موجود نیست' : 'No News Available'}
            </h3>
            <p style={{ color: colors.textSecondary }}>
              {language === 'fa' ? 'به زودی اخبار جدید منتشر خواهد شد' : 'New news will be published soon'}
            </p>
          </motion.div>
        </div>
      </div>
    );
  }

  const currentNews = activeNews[currentIndex];
  const catColor = categoryColors[currentNews?.category] || '#2196F3';

  return (
    <div className="news-orbit-wrapper" onMouseEnter={() => setIsPaused(true)} onMouseLeave={() => setIsPaused(false)}>
      <div className="container">
        {/* تایتل */}
        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <motion.h2
            initial={{ opacity: 0, y: -20 }}
            whileInView={{ opacity: 1, y: 0 }}
            className="gradient-text"
            style={{ fontSize: 'clamp(1.5rem, 3vw, 2rem)', fontWeight: 800, marginBottom: '5px' }}
          >
            {t('home.newsTitle')}
          </motion.h2>
        </div>

        {/* مدار فضایی */}
        <div className="orbit-container">
          {/* مدار بیرونی */}
          <div className="orbit orbit--outer" style={{ borderColor: `${catColor}20` }} />
          
          {/* مدار میانی */}
          <div className="orbit orbit--middle" style={{ borderColor: `${catColor}15` }} />
          
          {/* مدار داخلی */}
          <div className="orbit orbit--inner" style={{ borderColor: `${catColor}10` }} />

          {/* ذرات روی مدار */}
          {[...Array(3)].map((_, i) => (
            <motion.div
              key={`outer-${i}`}
              className="orbit-particle"
              animate={{ rotate: 360 }}
              transition={{ duration: 8 + i * 3, repeat: Infinity, ease: 'linear' }}
              style={{
                width: '8px',
                height: '8px',
                background: catColor,
                borderRadius: '50%',
                position: 'absolute',
                top: '50%',
                left: '50%',
                marginTop: '-4px',
                marginLeft: `${140 + i * 30}px`,
                transformOrigin: `-${140 + i * 30}px 50%`,
                boxShadow: `0 0 15px ${catColor}`,
                opacity: 0.7,
              }}
            />
          ))}

          {/* کارت مرکزی - حالت دایره‌ای */}
          <AnimatePresence mode="wait">
            <motion.div
              key={currentIndex}
              initial={{ opacity: 0, scale: 0.7, rotateY: 90 }}
              animate={{ opacity: 1, scale: 1, rotateY: 0 }}
              exit={{ opacity: 0, scale: 0.7, rotateY: -90 }}
              transition={{ duration: 0.6, ease: [0.4, 0, 0.2, 1] }}
              className="orbit-card glass"
              style={{
                background: `${colors.card}dd`,
                border: `1px solid ${catColor}40`,
                borderRadius: '50%',
                width: '280px',
                height: '280px',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                textAlign: 'center',
                padding: '30px',
                position: 'relative',
                zIndex: 10,
                boxShadow: `0 0 60px ${catColor}20, 0 0 120px ${catColor}10`,
                cursor: 'pointer',
                margin: '0 auto',
              }}
              onClick={() => setCurrentIndex((prev) => (prev + 1) % activeNews.length)}
            >
              {/* حلقه دور کارت */}
              <div style={{
                position: 'absolute',
                top: '-3px', left: '-3px', right: '-3px', bottom: '-3px',
                borderRadius: '50%',
                border: `2px solid ${catColor}30`,
                animation: 'orbit-spin 10s linear infinite',
              }} />

              {/* آیکون */}
              <motion.div
                animate={{ scale: [1, 1.1, 1] }}
                transition={{ duration: 2, repeat: Infinity }}
                style={{ fontSize: '2.5rem', marginBottom: '10px' }}
              >
                {categoryIcons[currentNews?.category] || '📋'}
              </motion.div>

              {/* دسته‌بندی */}
              <span style={{
                padding: '3px 12px',
                background: `${catColor}20`,
                color: catColor,
                borderRadius: '20px',
                fontSize: '0.7rem',
                fontWeight: 600,
                marginBottom: '8px',
              }}>
                {categoryLabels[language]?.[currentNews?.category] || currentNews?.category}
              </span>

              {/* تایتل */}
              <h4 style={{
                color: colors.text,
                fontSize: '0.9rem',
                fontWeight: 700,
                margin: '5px 0',
                lineHeight: 1.3,
                maxWidth: '200px',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                display: '-webkit-box',
                WebkitLineClamp: 2,
                WebkitBoxOrient: 'vertical',
              }}>
                {language === 'fa' ? currentNews?.title : (currentNews?.titleEn || currentNews?.title)}
              </h4>

              {/* تاریخ */}
              <span style={{ color: colors.textSecondary, fontSize: '0.7rem' }}>
                🕐 {currentNews?.date}
              </span>
            </motion.div>
          </AnimatePresence>

          {/* دایره‌های کوچک انتخاب‌گر */}
          <div className="orbit-dots">
            {activeNews.map((item, index) => (
              <motion.button
                key={index}
                whileHover={{ scale: 1.3 }}
                whileTap={{ scale: 0.9 }}
                onClick={() => setCurrentIndex(index)}
                style={{
                  width: index === currentIndex ? '14px' : '8px',
                  height: index === currentIndex ? '14px' : '8px',
                  borderRadius: '50%',
                  border: 'none',
                  background: index === currentIndex 
                    ? catColor 
                    : `${colors.textSecondary}40`,
                  cursor: 'pointer',
                  transition: 'all 0.3s ease',
                  boxShadow: index === currentIndex ? `0 0 10px ${catColor}` : 'none',
                }}
              />
            ))}
          </div>
        </div>
      </div>

      <style>{`
        @keyframes orbit-spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default NewsSlider;
